'use strict';
const fs=require('node:fs');const path=require('node:path');
const base=process.argv[2]??'http://127.0.0.1:8316',output=process.argv[3];
if(!/^http:\/\/(127\.0\.0\.1|localhost):\d+$/.test(base)||!output||!path.isAbsolute(output))throw new Error('Use localhost fixture URL and absolute output JSON path.');
const dimensions=[{width:1280,height:900},{width:390,height:844},{width:320,height:720}],counts=[12,120,600],runs=5;
function percentile(values,p){if(!values.length)return null;const sorted=[...values].sort((a,b)=>a-b);return sorted[Math.max(0,Math.ceil(sorted.length*p)-1)];}
(async()=>{const report={createdAt:new Date().toISOString(),settings:{dimensions,counts,runs,sourceQuality:'same 800x600 SVG, 120ms server delay, every four identities repeat src',browser:'existing Playwright Chromium only; no install'},state:'not-run',records:[],browserVersion:null};let browser;
 try{let playwright;try{playwright=require('playwright');}catch(error){if(!process.env.CODEX_PRIMARY_RUNTIME_NODE_MODULES)throw error;playwright=require(require.resolve('playwright',{paths:[process.env.CODEX_PRIMARY_RUNTIME_NODE_MODULES]}));}const {chromium}=playwright;browser=await chromium.launch({headless:true});report.browserVersion=browser.version();for(const phase of ['before','after'])for(const viewport of dimensions)for(const count of counts)for(let run=0;run<runs;run++){const context=await browser.newContext({viewport,reducedMotion:'reduce'});for(const cache of ['cold','warm']){const page=await context.newPage();await fetch(base+'/__reset');const remote=[];page.on('request',request=>{if(!request.url().startsWith(base+'/'))remote.push(request.url());});const url=base+'/'+phase+'.html?count='+count+'&run='+run;await page.goto(url,{waitUntil:'networkidle'});await page.waitForSelector('main img');const initial=await page.evaluate(()=>window.readFixtureMetrics());await page.evaluate(async()=>{for(let y=0;y<document.documentElement.scrollHeight;y+=Math.max(200,innerHeight-100)){scrollTo(0,y);await new Promise(resolve=>setTimeout(resolve,40));}await new Promise(resolve=>setTimeout(resolve,500));});const scrolled=await page.evaluate(()=>window.readFixtureMetrics());await page.locator('#identity-swap').click();await page.locator('#identity-swap').click();await page.locator('#source-swap').click();await page.locator('#source-swap').click();await page.waitForTimeout(300);const final=await page.evaluate(()=>window.readFixtureMetrics());const stats=await(await fetch(base+'/__stats')).json();report.records.push({phase,viewport,count,run,cache,initial,scrolled,final,serverImageRequests:stats.requests,duplicateServerRequests:stats.requests.length-new Set(stats.requests.map(row=>row.path)).size,remote});await page.close();}await context.close();}report.state='measured';report.summary=[];for(const phase of ['before','after'])for(const viewport of dimensions)for(const count of counts)for(const cache of ['cold','warm']){const rows=report.records.filter(row=>row.phase===phase&&row.viewport.width===viewport.width&&row.count===count&&row.cache===cache);const metrics={};for(const [name,get] of Object.entries({lcp:r=>r.initial.lcp,cls:r=>r.final.cls,firstVisibleMs:r=>r.initial.firstVisibleMs,firstImageLoadCallbackMs:r=>r.initial.firstImageLoadCallbackMs,serverRequests:r=>r.serverImageRequests.length,duplicateRequests:r=>r.duplicateServerRequests,criticalImageStartMs:r=>{const rows=r.initial.resources.filter(row=>new URL(row.name).searchParams.get('asset')==='0').map(row=>row.startTime);return rows.length?Math.min(...rows):null;},domCount:r=>r.final.domCount})){const values=rows.map(get).filter(value=>typeof value==='number'&&Number.isFinite(value));metrics[name]={measuredRuns:values.length,median:percentile(values,.5),p95:percentile(values,.95)};}report.summary.push({phase,viewport,count,cache,metrics});}}
 catch(error){report.reason=String(error.message);report.state=report.records.length?'partial':'not-run';report.browserMetricsNotMeasured=report.records.length===0;process.exitCode=report.records.length?1:2;}finally{if(browser)await browser.close();fs.mkdirSync(path.dirname(output),{recursive:true});fs.writeFileSync(output,JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({state:report.state,records:report.records.length,output}));}})();
